void imprimir_mapa()
{

    // Calcular las coordenadas de inicio de nuestra ventana de 20x20
    // Intentamos centrar al jugador restando 10 a su posicion actual
    int inicio_fila = jugador_x - 10;
    int inicio_col = jugador_y - 10;

    // Ajustar los limites para que la ventana no intente leer fuera de la matriz (0 - 50)
    // Si la ventana empieza antes de 0, la forzamos a 0
    if (inicio_fila < 0)
    {
        inicio_fila = 0;
    }
    if (inicio_col < 0)
    {
        inicio_col = 0;
    }
    // Si la ventana se pasa del límite superior (60 - 20 = 40), la detenemos en 40
    if (inicio_fila > FILAS - 20)
    {
        inicio_fila = FILAS - 20;
    }
    if (inicio_col > COLUMNAS - 20)
    {
        inicio_col = COLUMNAS - 20;
    }

    // Limpiamos la pantalla de la consola (mantiene la vista estática)
    system("cls");

    printf("\x1b[1;35m=== BITQUEST (20x20) ===\x1b[0m\n\n");

    // Imprimir la seccion de 20x20
    for (int i = inicio_fila; i < inicio_fila + 20; i++)
    {
        for (int j = inicio_col; j < inicio_col + 20; j++)
        {

            // Miramos el valor numerico de la matri y pintamos su caracter equivalente
            switch (mapas[nivel_actual][i][j])
            {
            case '#':
                // Muros: Azul
                printf("\x1b[94m%c%c", 178, 177);
                break;
            case '.':
                // Camino libre: Espacio vacío doble
                printf("  ");
                break;
            case 'P':
                // Jugador: Blanco
                printf("\x1b[37mP ");
                break;
            case 'M':
                // Moneda: Amarillo
                printf("\x1b[33m$ ");
                break;
            case 'K':
                // Llave: Cyan
                printf("\x1b[36m%c ", 190);
                break;
            case 'D':
                // Puerta: Rojo
                printf("\x1b[31m%c%c", 186, 186);
                break;
            case 'E':
                // Salida: Cyan
                printf("\x1b[36m%c%c", 176, 176);
                break;
            default:
                printf("  ");
                break;
            }
        }
        // Al terminar la fila, reiniciamos el color por seguridad y saltamos de línea
        printf("\x1b[0m\n");
    }
    // Asegurar que el color de la terminal regrese a la normalidad
    printf("\x1b[0m");
}

void cambiar_nivel(int nivel)
{
    nivel_actual = nivel - 1;

    // Buscamos la posición 'P' en el nuevo mapa para colocar al jugador
    // Si no se encuentra 'P', el jugador queda en (1,1) por defecto
    jugador_x = 1;
    jugador_y = 1;

    char (*mapa)[COLUMNAS] = mapas[nivel_actual];

    for (int i = 0; i < FILAS; i++)
    {
        for (int j = 0; j < COLUMNAS; j++)
        {
            if (mapa[i][j] == 'P')
            {
                jugador_x = i;
                jugador_y = j;
                return; // Encontramos la posición, salimos
            }
        }
    }
}

void mostrar_resumen_nivel(int nivel, int monedas_rec, int monedas_tot, int pasos, int puntaje_parcial)
{
    printf("\n\x1b[1;33m"); // Amarillo brillante
    printf("=================================\n");
    printf("  Nivel %d completado\n", nivel);
    printf("  Monedas recolectadas: %d / %d\n", monedas_rec, monedas_tot);
    printf("  Pasos realizados:     %d\n", pasos);
    printf("  Puntaje parcial:      %d\n", puntaje_parcial);
    printf("=================================\n");
    printf("\x1b[0m"); // Resetear color
    printf("Presiona cualquier tecla para continuar...\n");
    _getch();
}

void mostrar_resumen_final(int monedas_rec_total, int monedas_tot_total, int pasos_totales, int niveles_completados, int puntaje_final)
{
    system("cls");
    printf("\n\x1b[1;36m"); // Cyan brillante
    printf("=================================\n");
    printf("       JUEGO COMPLETADO\n");
    printf("=================================\n");
    printf("  Monedas totales: %d / %d\n", monedas_rec_total, monedas_tot_total);
    printf("  Pasos totales:   %d\n", pasos_totales);
    printf("  Niveles:         %d / 3\n", niveles_completados);
    printf("  Puntaje final:   %d\n", puntaje_final);
    printf("=================================\n");
    printf("\x1b[0m");
    printf("\nGracias por jugar BitQuest!\n");
}
